    """Bubble sort. Sorts the list in place and returns it."""
    n = len(arr)
    for i in range(n - 1):
        # Compare up to the last unsorted pair
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr
